<?php
use GhoroaHat\Rewards\{DB,Membership,Wallet};
add_filter( 'pre_wp_mail', '__return_true' );
global $wpdb,$ghr_expiry_count;$ghr_expiry_count=0;
function expiry_check($a,$b,$message){global $ghr_expiry_count;++$ghr_expiry_count;if($a!==$b){throw new RuntimeException($message.': '.var_export($a,true).' != '.var_export($b,true));}echo "PASS $message\n";}
function expiry_member(){global $wpdb;$run='expiry'.bin2hex(random_bytes(6));$id=wp_insert_user(array('user_login'=>$run,'user_email'=>$run.'@example.org','user_pass'=>wp_generate_password()));Membership::enroll($id);DB::update(DB::table('memberships'),array('status'=>'active','email_verified_at'=>DB::now(),'activated_at'=>DB::now()),array('user_id'=>$id));return $id;}
function make_expired($tx){global $wpdb;DB::query($wpdb->prepare('UPDATE '.DB::table('credit_lots').' SET expires_at=%s WHERE transaction_id=%d',gmdate('Y-m-d H:i:s',time()-60),$tx));}
$u=expiry_member();$key='ex'.bin2hex(random_bytes(6));$credit=Wallet::post($u,'trust',10000,$key,'earn',$key);make_expired($credit);expiry_check(Wallet::summary($u)['trust']['posted'],0,'Expired unused source is zero');Wallet::reverse_credit($credit,10000,$key.'-reverse','Refund expired award');expiry_check(Wallet::account($u,'trust')['posted'],0,'Refund of expired award creates no artificial debt');Wallet::reverse_credit($credit,10000,$key.'-reverse','Retry');expiry_check(Wallet::account($u,'trust')['posted'],0,'Expired award reversal is idempotent');
$v=expiry_member();$source=Wallet::post($v,'trust',10000,$key.'v','earn',$key);$reserve=Wallet::reserve($v,'trust',10000,$key.'-reserved-spend',hash('sha256','cart'));Wallet::bind($reserve['id'],$v,999992);Wallet::commit($reserve['id'],$v,999992);Wallet::reverse_credit($source,2000,$key.'v-reverse','Partially refunded source');expiry_check(Wallet::account($v,'trust')['posted'],-2000,'Spent source reversal creates only actual debt');Wallet::restore($reserve['id'],10000,$key.'v-restore');expiry_check(Wallet::account($v,'trust')['posted'],8000,'Cancelled redemption offsets prior reward debt');$a=Wallet::account($v,'trust');expiry_check((int)$wpdb->get_var($wpdb->prepare('SELECT SUM(remaining) FROM '.DB::table('credit_lots').' WHERE account_id=%d',$a['id'])),8000,'Restored lots exclude revoked grant portion');make_expired($source);expiry_check(Wallet::summary($v)['trust']['posted'],0,'Later expiry consumes only the real restored value');
$w=expiry_member();$grant=Wallet::post($w,'trust',10000,$key.'w','earn',$key);$spend=Wallet::reserve($w,'trust',10000,$key.'-spent-then-expired',hash('sha256','cart'));Wallet::bind($spend['id'],$w,999993);Wallet::commit($spend['id'],$w,999993);make_expired($grant);Wallet::reverse_credit($grant,2000,$key.'w-reverse','Source refund');Wallet::restore($spend['id'],10000,$key.'w-restore');expiry_check(Wallet::account($w,'trust')['posted'],0,'Expired restoration clears debt without renewing remaining credits');
expiry_check((int)$wpdb->get_var('SELECT COUNT(*) FROM '.DB::table('wallet_accounts').' a WHERE posted<>(SELECT COALESCE(SUM(amount),0) FROM '.DB::table('wallet_transactions').' t WHERE t.account_id=a.id)'),0,'Expiry recovery projections match immutable ledger');
echo "EXPIRY PASS: $ghr_expiry_count assertions\n";
